// Targeted follow-up for the disableTooltip -> hideHint rename on PillComponent subclasses.
// Usage: node fix.mjs <workspaceRoot> <file1> <file2> ...   (paths relative to root)
import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const [root, ...files] = process.argv.slice(2);
let total = 0;

for (const rel of files) {
    const p = join(root, rel);
    let src = readFileSync(p, "utf8");
    const before = src;

    // 1) Element tags of PillComponent and its subclasses: rewrite the input name inside the tag.
    //    Scan each tag to its real closing '>' (quotes respected, so "count > 5" is not a tag end).
    const tagStart = /<app-(?:fancy-|status-)?pill[\s/>]/g;
    let out = "";
    let pos = 0;
    let m;
    while ((m = tagStart.exec(src)) !== null) {
        let i = m.index + m[0].length;
        let quote = null;
        for (; i < src.length; i++) {
            const c = src[i];
            if (quote) { if (c === quote) quote = null; continue; }
            if (c === '"' || c === "'") { quote = c; continue; }
            if (c === ">") break;
        }
        const tag = src.slice(m.index, i + 1);
        const fixed = tag
            .replace(/\[disableTooltip\]=/g, "[hideHint]=")
            .replace(/(\s)disableTooltip(?=[\s/>=])/g, "$1hideHint");
        out += src.slice(pos, m.index) + fixed;
        pos = i + 1;
        tagStart.lastIndex = pos;
    }
    out += src.slice(pos);
    src = out;

    // 2) Reads through a typed reference: x.disableTooltip() -- but not CardComponent reads
    //    (lines mentioning card() or the #summary card ref).
    src = src
        .split("\n")
        .map(line => (/card\(\)|summary\./.test(line) ? line : line.replace(/\.disableTooltip\(\)/g, ".hideHint()")))
        .join("\n");

    // 3) Bare reads inside the pill base/subclass templates and class.
    if (/(fancy-pill|status-pill)\.component\.ts$/.test(rel)) {
        src = src.replace(/!disableTooltip\(\)/g, "!hideHint()").replace(/this\.disableTooltip\(\)/g, "this.hideHint()");
    }

    if (src !== before) {
        writeFileSync(p, src, "utf8");
        total++;
        console.log("changed", rel);
    }
}
console.log("files changed:", total);

